-- Generated by `make contracts` from contracts/ (schema customProperties.conformedDimensions). Do not edit: change the contract and regenerate.
-- A place label matches dim_place by name (label_key: case, edge spaces and dots ignored) at the levels the
-- source reports, or by its contract's conformedDimensions label; FIPS sources build the key (county 000 is
-- the Census file's state row). A label that names no place in dim_place is left out.
select 'cdc_nndss_weekly' as dataset_id, k.place_key as place_key, cast(src."year" as bigint) as year,
    count(*) as row_count
from {{ ref('int_cdc_nndss_weekly') }} as src
join (
        select regexp_replace(upper(trim(CAST(place_name AS VARCHAR), ' ' || chr(9) || chr(10) || chr(11) || chr(12) || chr(13))), '[.]', '', 'g') as label_key, place_key
        from {{ ref('dim_place') }}
        where place_level in ('nation', 'region', 'state', 'city')
        union select 'US RESIDENTS', 'USA'
        union select 'COMMONWEALTH OF NORTHERN MARIANA ISLANDS', 'US-69'
    ) as k on regexp_replace(upper(trim(CAST(src."states" AS VARCHAR), ' ' || chr(9) || chr(10) || chr(11) || chr(12) || chr(13))), '[.]', '', 'g') = k.label_key
where src."states" IS NOT NULL and src."year" IS NOT NULL
group by all
union all
select 'census_county_pop' as dataset_id, 'US-' || src."state_fips" || CASE WHEN src."county_fips" = '000' THEN '' ELSE src."county_fips" END as place_key, cast(src."year" as bigint) as year,
    count(*) as row_count
from {{ ref('int_census_county_pop') }} as src
where src."state_fips" IS NOT NULL and src."year" IS NOT NULL
group by all
